import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiUpload,
  FiUsers,
  FiX,
  FiImage,
  FiMail,
  FiPhone,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const AdminLeadership = () => {

  // =====================================================
  // LANGUAGE
  // =====================================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  // =====================================================
  // TRANSLATION FALLBACK
  // =====================================================

  const tr = (
    key,
    english,
    khmer
  ) => {

    const value = t(key);

    if (
      value &&
      value !== key
    ) {
      return value;
    }

    return isKhmer
      ? khmer
      : english;

  };


  // =====================================================
  // CURRENT LANGUAGE FIELD
  // =====================================================

  const nameField =
    isKhmer
      ? 'name_km'
      : 'name_en';


  const positionField =
    isKhmer
      ? 'position_km'
      : 'position_en';


  const bioField =
    isKhmer
      ? 'bio_km'
      : 'bio_en';


  // =====================================================
  // STATE
  // =====================================================

  const [
    members,
    setMembers,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    saving,
    setSaving,
  ] = useState(false);


  const [
    showModal,
    setShowModal,
  ] = useState(false);


  const [
    editingMember,
    setEditingMember,
  ] = useState(null);


  const [
    imageFile,
    setImageFile,
  ] = useState(null);


  const [
    imagePreview,
    setImagePreview,
  ] = useState(null);


  const [
    imageRemoved,
    setImageRemoved,
  ] = useState(false);


  // =====================================================
  // FORM
  // =====================================================

  const [
    formData,
    setFormData,
  ] = useState({

    name_en: '',
    position_en: '',
    bio_en: '',

    name_km: '',
    position_km: '',
    bio_km: '',

    email: '',
    phone: '',
    facebook_url: '',
    linkedin_url: '',

    is_active: true,
    order: 0,

  });


  // =====================================================
  // API BASE URL
  // =====================================================

  const API_BASE_URL =
    process.env.REACT_APP_API_URL ||
    'http://127.0.0.1:8000';


  // =====================================================
  // IMAGE URL
  // =====================================================

  const getImageUrl = (
    image
  ) => {

    if (!image) {
      return null;
    }


    if (
      image.startsWith(
        'http://'
      ) ||
      image.startsWith(
        'https://'
      ) ||
      image.startsWith(
        'blob:'
      )
    ) {

      return image;

    }


    if (
      image.startsWith('/')
    ) {

      return `${API_BASE_URL}${image}`;

    }


    return `${API_BASE_URL}/${image}`;

  };


  // =====================================================
  // LOCALIZED NAME
  // =====================================================

  const getMemberName = (
    member
  ) => {

    if (!member) {
      return '';
    }


    if (isKhmer) {

      return (
        member.name_km ||
        member.name_en ||
        ''
      );

    }


    return (
      member.name_en ||
      member.name_km ||
      ''
    );

  };


  // =====================================================
  // LOCALIZED POSITION
  // =====================================================

  const getMemberPosition = (
    member
  ) => {

    if (!member) {
      return '';
    }


    if (isKhmer) {

      return (
        member.position_km ||
        member.position_en ||
        ''
      );

    }


    return (
      member.position_en ||
      member.position_km ||
      ''
    );

  };


  // =====================================================
  // FETCH MEMBERS
  // =====================================================

  const fetchMembers = async () => {

    try {

      setLoading(true);


      const response =
        await api.get(
          '/api/leadership/'
        );


      if (
        Array.isArray(
          response.data
        )
      ) {

        setMembers(
          response.data
        );

      } else if (
        Array.isArray(
          response.data?.items
        )
      ) {

        setMembers(
          response.data.items
        );

      } else {

        setMembers([]);

      }

    } catch (error) {

      console.error(
        'Load Leadership Error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'leadership.loadFailed',
            'Failed to load leadership team.',
            'មិនអាចផ្ទុកក្រុមថ្នាក់ដឹកនាំបានទេ។'
          )
        )
      );

    } finally {

      setLoading(false);

    }

  };


  // =====================================================
  // LOAD
  // =====================================================

  useEffect(() => {

    fetchMembers();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  // =====================================================
  // CLEAN BLOB
  // =====================================================

  useEffect(() => {

    return () => {

      if (
        imagePreview &&
        imagePreview.startsWith(
          'blob:'
        )
      ) {

        URL.revokeObjectURL(
          imagePreview
        );

      }

    };

  }, [imagePreview]);


  // =====================================================
  // RESET FORM
  // =====================================================

  const resetForm = () => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setFormData({

      name_en: '',
      position_en: '',
      bio_en: '',

      name_km: '',
      position_km: '',
      bio_km: '',

      email: '',
      phone: '',
      facebook_url: '',
      linkedin_url: '',

      is_active: true,
      order: 0,

    });


    setEditingMember(null);

    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(false);

  };


  // =====================================================
  // ADD
  // =====================================================

  const handleAdd = () => {

    resetForm();

    setShowModal(true);

  };


  // =====================================================
  // EDIT
  // =====================================================

  const handleEdit = (
    member
  ) => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setEditingMember(
      member
    );


    setFormData({

      name_en:
        member.name_en || '',

      position_en:
        member.position_en || '',

      bio_en:
        member.bio_en || '',


      name_km:
        member.name_km || '',

      position_km:
        member.position_km || '',

      bio_km:
        member.bio_km || '',


      email:
        member.email || '',

      phone:
        member.phone || '',

      facebook_url:
        member.facebook_url || '',

      linkedin_url:
        member.linkedin_url || '',

      is_active:
        member.is_active ?? true,

      order:
        Number(
          member.order
        ) || 0,

    });


    setImageFile(null);

    setImageRemoved(false);


    setImagePreview(
      member.image
        ? getImageUrl(
            member.image
          )
        : null
    );


    setShowModal(true);

  };


  // =====================================================
  // CLOSE MODAL
  // =====================================================

  const handleCloseModal = () => {

    if (saving) {
      return;
    }


    setShowModal(false);

    resetForm();

  };


  // =====================================================
  // INPUT CHANGE
  // =====================================================

  const handleChange = (
    e
  ) => {

    const {
      name,
      value,
      type,
      checked,
    } = e.target;


    setFormData(
      (previous) => ({

        ...previous,

        [name]:
          type === 'checkbox'
            ? checked
            : value,

      })
    );

  };


  // =====================================================
  // IMAGE CHANGE
  // =====================================================

  const handleImageChange = (
    e
  ) => {

    const file =
      e.target.files?.[0];


    if (!file) {
      return;
    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        tr(
          'leadership.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាព JPG, JPEG, PNG ឬ WEBP។'
        )
      );


      e.target.value = '';

      return;

    }


    if (
      file.size >
      5 * 1024 * 1024
    ) {

      toast.error(
        tr(
          'leadership.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );


      e.target.value = '';

      return;

    }


    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(
      file
    );


    setImagePreview(
      URL.createObjectURL(
        file
      )
    );


    setImageRemoved(
      false
    );

  };


  // =====================================================
  // REMOVE IMAGE
  // =====================================================

  const handleRemoveImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(true);

  };


  // =====================================================
  // VALIDATE CURRENT LANGUAGE ONLY
  // =====================================================

  const validateForm = () => {

    const currentName =
      String(
        formData[
          nameField
        ] || ''
      ).trim();


    const currentPosition =
      String(
        formData[
          positionField
        ] || ''
      ).trim();


    if (!currentName) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលឈ្មោះ។'
          : 'Name is required.'
      );

      return false;

    }


    if (!currentPosition) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលតួនាទី។'
          : 'Position is required.'
      );

      return false;

    }


    return true;

  };


  // =====================================================
  // BUILD PAYLOAD
  // =====================================================

  const buildPayload = () => {

    const data =
      new FormData();


    const currentName =
      String(
        formData[
          nameField
        ] || ''
      ).trim();


    const currentPosition =
      String(
        formData[
          positionField
        ] || ''
      ).trim();


    const currentBio =
      String(
        formData[
          bioField
        ] || ''
      ).trim();


    // =================================================
    // CREATE
    // =================================================

    if (!editingMember) {

      /*
        Backend មួយចំនួន require
        name_en/name_km និង
        position_en/position_km។

        ដូច្នេះពេល Create ដំបូង
        យើងយក content ដែលអ្នកកំពុងបញ្ចូល
        ទៅដាក់ជាភាសាទាំងពីរជាបណ្ដោះអាសន្ន។

        បន្ទាប់មកអ្នកអាចប្ដូរ EN/KM
        ហើយ Edit ភាសានីមួយៗដោយឡែកបាន។
      */


      const nameEn =
        formData.name_en.trim() ||
        currentName;


      const nameKm =
        formData.name_km.trim() ||
        currentName;


      const positionEn =
        formData.position_en.trim() ||
        currentPosition;


      const positionKm =
        formData.position_km.trim() ||
        currentPosition;


      const bioEn =
        formData.bio_en.trim() ||
        currentBio;


      const bioKm =
        formData.bio_km.trim() ||
        currentBio;


      data.append(
        'name_en',
        nameEn
      );


      data.append(
        'name_km',
        nameKm
      );


      data.append(
        'position_en',
        positionEn
      );


      data.append(
        'position_km',
        positionKm
      );


      data.append(
        'bio_en',
        bioEn
      );


      data.append(
        'bio_km',
        bioKm
      );

    }


    // =================================================
    // EDIT
    // ONLY CURRENT LANGUAGE
    // =================================================

    if (editingMember) {

      data.append(
        nameField,
        currentName
      );


      data.append(
        positionField,
        currentPosition
      );


      data.append(
        bioField,
        currentBio
      );

    }


    // =================================================
    // COMMON
    // =================================================

    data.append(
      'email',
      formData.email.trim()
    );


    data.append(
      'phone',
      formData.phone.trim()
    );


    data.append(
      'facebook_url',
      formData.facebook_url.trim()
    );


    data.append(
      'linkedin_url',
      formData.linkedin_url.trim()
    );


    data.append(
      'is_active',
      String(
        formData.is_active
      )
    );


    data.append(
      'order',
      String(
        Number(
          formData.order
        ) || 0
      )
    );


    // =================================================
    // IMAGE
    // =================================================

    if (imageFile) {

      data.append(
        'image',
        imageFile
      );

    }


    if (
      editingMember &&
      imageRemoved &&
      !imageFile
    ) {

      data.append(
        'remove_image',
        'true'
      );

    }


    return data;

  };


  // =====================================================
  // SUBMIT
  // =====================================================

  const handleSubmit = async (
    e
  ) => {

    e.preventDefault();


    if (!validateForm()) {
      return;
    }


    try {

      setSaving(true);


      const data =
        buildPayload();


      // =================================================
      // UPDATE
      // =================================================

      if (editingMember) {

        await api.put(
          `/api/leadership/${editingMember.id}`,
          data
        );


        toast.success(
          tr(
            'leadership.updatedSuccess',
            'Leadership member updated successfully.',
            'បានកែប្រែសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
          )
        );

      }


      // =================================================
      // CREATE
      // =================================================

      else {

        await api.post(
          '/api/leadership/',
          data
        );


        toast.success(
          tr(
            'leadership.createdSuccess',
            'Leadership member added successfully.',
            'បានបន្ថែមសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
          )
        );

      }


      setShowModal(false);

      resetForm();


      await fetchMembers();

    } catch (error) {

      console.error(
        'Save Leadership Error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'leadership.saveFailed',
            'Failed to save leadership member.',
            'មិនអាចរក្សាទុកសមាជិកថ្នាក់ដឹកនាំបានទេ។'
          )
        )
      );

    } finally {

      setSaving(false);

    }

  };


  // =====================================================
  // DELETE
  // =====================================================

  const handleDelete = async (
    member
  ) => {

    const memberName =
      getMemberName(
        member
      );


    const confirmed =
      window.confirm(
        `${tr(
          'leadership.deleteConfirm',
          'Are you sure you want to delete',
          'តើអ្នកប្រាកដថាចង់លុប'
        )} "${memberName}"?`
      );


    if (!confirmed) {
      return;
    }


    try {

      await api.delete(
        `/api/leadership/${member.id}`
      );


      toast.success(
        tr(
          'leadership.deletedSuccess',
          'Leadership member deleted successfully.',
          'បានលុបសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
        )
      );


      await fetchMembers();

    } catch (error) {

      console.error(
        'Delete Leadership Error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'leadership.deleteFailed',
            'Failed to delete leadership member.',
            'មិនអាចលុបសមាជិកថ្នាក់ដឹកនាំបានទេ។'
          )
        )
      );

    }

  };


  // =====================================================
  // ACTIVE COUNT
  // =====================================================

  const activeCount =
    members.filter(
      (member) =>
        member.is_active
    ).length;


  // =====================================================
  // RENDER
  // =====================================================

  return (

    <div
      className={`w-full ${
        isKhmer
          ? 'font-khmer'
          : ''
      }`}
    >


      {/* =================================================
          HEADER
      ================================================== */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-10
              h-10
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >

            <FiUsers
              size={18}
            />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              {tr(
                'leadership.title',
                'Leadership Team',
                'ក្រុមថ្នាក់ដឹកនាំ'
              )}
            </h1>


            <p
              className="
                text-xs
                md:text-sm
                text-blue-400
                mt-1
              "
            >
              {tr(
                'leadership.subtitle',
                'Manage SC Academy leadership members',
                'គ្រប់គ្រងសមាជិកថ្នាក់ដឹកនាំ SC Academy'
              )}
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            handleAdd
          }

          className="
            h-10
            px-4
            inline-flex
            items-center
            justify-center
            gap-2
            bg-red-600
            text-white
            rounded-lg
            text-sm
            font-semibold
            shadow-sm
            hover:bg-red-700
            hover:shadow-md
            transition-all
          "
        >

          <FiPlus
            size={17}
          />


          {tr(
            'leadership.addMember',
            'Add Member',
            'បន្ថែមសមាជិក'
          )}

        </button>

      </div>


      {/* =================================================
          SUMMARY
      ================================================== */}

      <div
        className="
          grid
          grid-cols-1
          sm:grid-cols-2
          gap-3
          mb-6
        "
      >

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {tr(
                  'leadership.totalMembers',
                  'Total Members',
                  'សមាជិកសរុប'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {members.length}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiUsers
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {tr(
                  'leadership.activeMembers',
                  'Active Members',
                  'សមាជិកសកម្ម'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >
                {activeCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiUsers
                size={18}
              />

            </div>

          </div>

        </div>

      </div>


      {/* =================================================
          TABLE CARD
      ================================================== */}

      <div
        className="
          bg-white
          border
          border-blue-200
          rounded-xl
          shadow-sm
          overflow-hidden
        "
      >

        <div
          className="
            px-5
            py-4
            border-b
            border-blue-200
          "
        >

          <h2
            className="
              text-sm
              font-bold
              text-blue-900
            "
          >
            {tr(
              'leadership.teamList',
              'Leadership Team',
              'បញ្ជីក្រុមថ្នាក់ដឹកនាំ'
            )}
          </h2>


          <p
            className="
              text-xs
              text-blue-300
              mt-1
            "
          >
            {members.length}{' '}

            {members.length === 1
              ? tr(
                  'leadership.member',
                  'member',
                  'សមាជិក'
                )
              : tr(
                  'leadership.memberPlural',
                  'members',
                  'សមាជិក'
                )}
          </p>

        </div>


        {
          loading ? (

            <div
              className="
                min-h-[300px]
                flex
                items-center
                justify-center
              "
            >

              <div className="text-center">

                <div
                  className="
                    w-10
                    h-10
                    border-4
                    border-blue-200
                    border-t-blue-900
                    rounded-full
                    animate-spin
                    mx-auto
                  "
                />


                <p
                  className="
                    text-xs
                    text-blue-300
                    mt-3
                  "
                >
                  {tr(
                    'common.loading',
                    'Loading...',
                    'កំពុងផ្ទុក...'
                  )}
                </p>

              </div>

            </div>

          ) : members.length === 0 ? (

            <div
              className="
                min-h-[320px]
                flex
                items-center
                justify-center
                p-6
              "
            >

              <div className="text-center">

                <div
                  className="
                    w-16
                    h-16
                    bg-blue-50
                    text-blue-900
                    rounded-full
                    flex
                    items-center
                    justify-center
                    mx-auto
                    mb-4
                  "
                >

                  <FiUsers
                    size={26}
                  />

                </div>


                <h3
                  className="
                    text-base
                    font-bold
                    text-blue-900
                  "
                >
                  {tr(
                    'leadership.noMembers',
                    'No leadership members',
                    'មិនមានសមាជិកថ្នាក់ដឹកនាំ'
                  )}
                </h3>


                <p
                  className="
                    text-sm
                    text-blue-400
                    mt-1
                    mb-4
                  "
                >
                  {tr(
                    'leadership.addFirstMember',
                    'Add your first leadership member.',
                    'សូមបន្ថែមសមាជិកថ្នាក់ដឹកនាំដំបូង។'
                  )}
                </p>


                <button
                  type="button"

                  onClick={
                    handleAdd
                  }

                  className="
                    inline-flex
                    items-center
                    gap-2
                    bg-red-600
                    text-white
                    px-4
                    py-2.5
                    rounded-lg
                    text-sm
                    font-semibold
                    hover:bg-red-700
                    transition
                  "
                >

                  <FiPlus />


                  {tr(
                    'leadership.addMember',
                    'Add Member',
                    'បន្ថែមសមាជិក'
                  )}

                </button>

              </div>

            </div>

          ) : (

            <div
              className="
                overflow-x-auto
              "
            >

              <table
                className="
                  w-full
                  min-w-[950px]
                "
              >

                <thead>

                  <tr
                    className="
                      bg-blue-50
                      border-b
                      border-blue-200
                    "
                  >

                    <th
                      className="
                        px-5
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      #
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {tr(
                        'leadership.member',
                        'Member',
                        'សមាជិក'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {tr(
                        'leadership.position',
                        'Position',
                        'តួនាទី'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {tr(
                        'leadership.contact',
                        'Contact',
                        'ទំនាក់ទំនង'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-center
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {tr(
                        'common.status',
                        'Status',
                        'ស្ថានភាព'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-center
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {tr(
                        'leadership.order',
                        'Order',
                        'លំដាប់'
                      )}
                    </th>


                    <th
                      className="
                        px-5
                        py-3.5
                        text-right
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {tr(
                        'common.actions',
                        'Actions',
                        'សកម្មភាព'
                      )}
                    </th>

                  </tr>

                </thead>


                <tbody
                  className="
                    divide-y
                    divide-blue-100
                  "
                >

                  {
                    members.map(
                      (
                        member,
                        index
                      ) => {

                        const memberName =
                          getMemberName(
                            member
                          );


                        const memberPosition =
                          getMemberPosition(
                            member
                          );


                        return (

                          <tr
                            key={
                              member.id
                            }

                            className="
                              hover:bg-blue-50/50
                              transition-colors
                            "
                          >

                            <td
                              className="
                                px-5
                                py-4
                                text-sm
                                text-blue-400
                              "
                            >
                              {
                                String(
                                  index + 1
                                ).padStart(
                                  2,
                                  '0'
                                )
                              }
                            </td>


                            <td
                              className="
                                px-4
                                py-4
                              "
                            >

                              <div
                                className="
                                  flex
                                  items-center
                                  gap-3
                                "
                              >

                                {
                                  member.image ? (

                                    <img
                                      src={
                                        getImageUrl(
                                          member.image
                                        )
                                      }

                                      alt={
                                        memberName
                                      }

                                      className="
                                        w-[52px]
                                        h-[52px]
                                        rounded-xl
                                        object-cover
                                        border
                                        border-blue-200
                                        shadow-sm
                                        flex-shrink-0
                                      "
                                    />

                                  ) : (

                                    <div
                                      className="
                                        w-[52px]
                                        h-[52px]
                                        rounded-xl
                                        bg-blue-50
                                        text-blue-900
                                        flex
                                        items-center
                                        justify-center
                                        flex-shrink-0
                                      "
                                    >

                                      <FiUsers
                                        size={20}
                                      />

                                    </div>

                                  )
                                }


                                <div
                                  className="
                                    min-w-0
                                  "
                                >

                                  <p
                                    className="
                                      text-sm
                                      font-bold
                                      text-blue-900
                                      truncate
                                      max-w-[220px]
                                    "
                                  >
                                    {
                                      memberName ||
                                      '—'
                                    }
                                  </p>


                                  {
                                    member.email && (

                                      <p
                                        className="
                                          text-xs
                                          text-blue-400
                                          mt-1
                                          truncate
                                          max-w-[220px]
                                        "
                                      >
                                        {
                                          member.email
                                        }
                                      </p>

                                    )
                                  }

                                </div>

                              </div>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                              "
                            >

                              <span
                                className="
                                  text-sm
                                  font-medium
                                  text-blue-900
                                "
                              >
                                {
                                  memberPosition ||
                                  '—'
                                }
                              </span>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                              "
                            >

                              <div
                                className="
                                  space-y-1.5
                                "
                              >

                                {
                                  member.phone && (

                                    <div
                                      className="
                                        flex
                                        items-center
                                        gap-2
                                        text-xs
                                        text-blue-500
                                      "
                                    >

                                      <FiPhone
                                        size={13}
                                        className="text-red-600"
                                      />


                                      <span>
                                        {
                                          member.phone
                                        }
                                      </span>

                                    </div>

                                  )
                                }


                                {
                                  member.email && (

                                    <div
                                      className="
                                        flex
                                        items-center
                                        gap-2
                                        text-xs
                                        text-blue-500
                                      "
                                    >

                                      <FiMail
                                        size={13}
                                        className="text-blue-900"
                                      />


                                      <span
                                        className="
                                          truncate
                                          max-w-[180px]
                                        "
                                      >
                                        {
                                          member.email
                                        }
                                      </span>

                                    </div>

                                  )
                                }


                                {
                                  !member.phone &&
                                  !member.email && (

                                    <span
                                      className="
                                        text-sm
                                        text-blue-300
                                      "
                                    >
                                      —
                                    </span>

                                  )
                                }

                              </div>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                                text-center
                              "
                            >

                              <span
                                className={`
                                  inline-flex
                                  items-center
                                  gap-1.5
                                  px-2.5
                                  py-1
                                  rounded-full
                                  text-[11px]
                                  font-semibold

                                  ${
                                    member.is_active
                                      ? 'bg-blue-50 text-blue-700'
                                      : 'bg-red-50 text-red-600'
                                  }
                                `}
                              >

                                <span
                                  className={`
                                    w-1.5
                                    h-1.5
                                    rounded-full

                                    ${
                                      member.is_active
                                        ? 'bg-blue-500'
                                        : 'bg-red-500'
                                    }
                                  `}
                                />


                                {
                                  member.is_active
                                    ? tr(
                                        'common.active',
                                        'Active',
                                        'សកម្ម'
                                      )
                                    : tr(
                                        'common.inactive',
                                        'Inactive',
                                        'អសកម្ម'
                                      )
                                }

                              </span>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                                text-center
                              "
                            >

                              <span
                                className="
                                  inline-flex
                                  items-center
                                  justify-center
                                  min-w-[30px]
                                  h-[30px]
                                  px-2
                                  bg-blue-50
                                  rounded-lg
                                  text-xs
                                  font-bold
                                  text-blue-900
                                "
                              >
                                {
                                  member.order ??
                                  0
                                }
                              </span>

                            </td>


                            <td
                              className="
                                px-5
                                py-4
                              "
                            >

                              <div
                                className="
                                  flex
                                  items-center
                                  justify-end
                                  gap-2
                                "
                              >

                                <button
                                  type="button"

                                  onClick={() =>
                                    handleEdit(
                                      member
                                    )
                                  }

                                  title={tr(
                                    'common.edit',
                                    'Edit',
                                    'កែប្រែ'
                                  )}

                                  className="
                                    w-9
                                    h-9
                                    rounded-lg
                                    bg-blue-50
                                    text-blue-900
                                    flex
                                    items-center
                                    justify-center
                                    hover:bg-blue-900
                                    hover:text-white
                                    transition
                                  "
                                >

                                  <FiEdit2
                                    size={15}
                                  />

                                </button>


                                <button
                                  type="button"

                                  onClick={() =>
                                    handleDelete(
                                      member
                                    )
                                  }

                                  title={tr(
                                    'common.delete',
                                    'Delete',
                                    'លុប'
                                  )}

                                  className="
                                    w-9
                                    h-9
                                    rounded-lg
                                    bg-red-50
                                    text-red-600
                                    flex
                                    items-center
                                    justify-center
                                    hover:bg-red-600
                                    hover:text-white
                                    transition
                                  "
                                >

                                  <FiTrash2
                                    size={15}
                                  />

                                </button>

                              </div>

                            </td>

                          </tr>

                        );

                      }
                    )
                  }

                </tbody>

              </table>

            </div>

          )
        }

      </div>


      {/* =================================================
          MODAL
      ================================================== */}

      {
        showModal && (

          <div
            className="
              fixed
              inset-0
              z-[9999]
              bg-blue-900/50
              backdrop-blur-[2px]
              flex
              items-center
              justify-center
              p-4
            "

            onMouseDown={(e) => {

              if (
                e.target ===
                e.currentTarget &&
                !saving
              ) {

                handleCloseModal();

              }

            }}
          >

            <div
              className="
                bg-white
                w-full
                max-w-[900px]
                max-h-[92vh]
                rounded-2xl
                shadow-2xl
                overflow-hidden
                flex
                flex-col
              "
            >


              {/* =================================================
                  MODAL HEADER
              ================================================== */}

              <div
                className="
                  px-5
                  md:px-6
                  py-4
                  bg-blue-900
                  flex
                  items-center
                  justify-between
                  flex-shrink-0
                "
              >

                <div
                  className="
                    flex
                    items-center
                    gap-3
                  "
                >

                  <div
                    className="
                      w-10
                      h-10
                      bg-red-600
                      rounded-lg
                      flex
                      items-center
                      justify-center
                      text-white
                    "
                  >

                    {
                      editingMember
                        ? (
                            <FiEdit2
                              size={17}
                            />
                          )
                        : (
                            <FiPlus
                              size={18}
                            />
                          )
                    }

                  </div>


                  <div>

                    <p
                      className="
                        text-white/50
                        text-[10px]
                        uppercase
                        font-bold
                        tracking-widest
                      "
                    >
                      {tr(
                        'leadership.management',
                        'Leadership Management',
                        'ការគ្រប់គ្រងថ្នាក់ដឹកនាំ'
                      )}
                    </p>


                    <h2
                      className="
                        text-white
                        text-lg
                        font-bold
                        mt-0.5
                      "
                    >
                      {
                        editingMember
                          ? tr(
                              'leadership.editMember',
                              'Edit Member',
                              'កែប្រែសមាជិក'
                            )
                          : tr(
                              'leadership.addLeadershipMember',
                              'Add Leadership Member',
                              'បន្ថែមសមាជិកថ្នាក់ដឹកនាំ'
                            )
                      }
                    </h2>

                  </div>

                </div>


                <button
                  type="button"

                  onClick={
                    handleCloseModal
                  }

                  disabled={
                    saving
                  }

                  className="
                    w-9
                    h-9
                    bg-white/10
                    rounded-lg
                    text-white
                    flex
                    items-center
                    justify-center
                    hover:bg-red-600
                    disabled:opacity-50
                    transition
                  "
                >

                  <FiX
                    size={19}
                  />

                </button>

              </div>


              {/* =================================================
                  FORM
              ================================================== */}

              <form
                onSubmit={
                  handleSubmit
                }

                className="
                  flex
                  flex-col
                  min-h-0
                "
              >

                <div
                  className="
                    p-5
                    md:p-6
                    overflow-y-auto
                  "
                >


                  {/* =================================================
                      PHOTO
                  ================================================== */}

                  <div
                    className="
                      bg-blue-50
                      border
                      border-blue-200
                      rounded-xl
                      p-4
                      mb-6
                    "
                  >

                    <label
                      className="
                        block
                        text-sm
                        font-bold
                        text-blue-900
                        mb-3
                      "
                    >
                      {tr(
                        'leadership.memberPhoto',
                        'Member Photo',
                        'រូបភាពសមាជិក'
                      )}
                    </label>


                    <div
                      className="
                        flex
                        flex-col
                        sm:flex-row
                        sm:items-center
                        gap-4
                      "
                    >

                      <div
                        className="
                          w-[110px]
                          h-[110px]
                          rounded-xl
                          overflow-hidden
                          bg-white
                          border
                          border-blue-200
                          flex
                          items-center
                          justify-center
                          flex-shrink-0
                        "
                      >

                        {
                          imagePreview ? (

                            <img
                              src={
                                imagePreview
                              }

                              alt="Preview"

                              className="
                                w-full
                                h-full
                                object-cover
                              "
                            />

                          ) : (

                            <FiImage
                              size={30}
                              className="text-blue-300"
                            />

                          )
                        }

                      </div>


                      <div>

                        <div
                          className="
                            flex
                            flex-wrap
                            gap-2
                          "
                        >

                          <label
                            className="
                              h-10
                              px-4
                              bg-blue-900
                              text-white
                              rounded-lg
                              text-sm
                              font-semibold
                              inline-flex
                              items-center
                              justify-center
                              gap-2
                              cursor-pointer
                              hover:bg-blue-800
                              transition
                            "
                          >

                            <FiUpload
                              size={16}
                            />


                            {tr(
                              'leadership.chooseImage',
                              'Choose Image',
                              'ជ្រើសរើសរូបភាព'
                            )}


                            <input
                              type="file"

                              accept="image/jpeg,image/jpg,image/png,image/webp"

                              onChange={
                                handleImageChange
                              }

                              className="hidden"
                            />

                          </label>


                          {
                            imagePreview && (

                              <button
                                type="button"

                                onClick={
                                  handleRemoveImage
                                }

                                className="
                                  h-10
                                  px-4
                                  bg-red-50
                                  text-red-600
                                  rounded-lg
                                  text-sm
                                  font-semibold
                                  hover:bg-red-600
                                  hover:text-white
                                  transition
                                "
                              >
                                {tr(
                                  'common.remove',
                                  'Remove',
                                  'ដកចេញ'
                                )}
                              </button>

                            )
                          }

                        </div>


                        <p
                          className="
                            text-xs
                            text-blue-300
                            mt-2
                          "
                        >
                          {tr(
                            'leadership.imageHelp',
                            'JPG, JPEG, PNG or WEBP. Maximum 5 MB.',
                            'JPG, JPEG, PNG ឬ WEBP។ ទំហំអតិបរមា 5 MB។'
                          )}
                        </p>

                      </div>

                    </div>

                  </div>


                  {/* =================================================
                      LANGUAGE CONTENT - ONE FORM ONLY
                  ================================================== */}

                  <div
                    className="
                      border
                      border-blue-200
                      rounded-xl
                      overflow-hidden
                      mb-5
                    "
                  >

                    <div
                      className="
                        px-4
                        py-3
                        bg-blue-50
                        border-b
                        border-blue-200
                      "
                    >

                      <h3
                        className="
                          text-sm
                          font-bold
                          text-blue-900
                        "
                      >
                        {isKhmer
                          ? 'ព័ត៌មានសមាជិក'
                          : 'Member Information'}
                      </h3>

                    </div>


                    <div
                      className="
                        p-4
                        space-y-4
                      "
                    >


                      {/* NAME */}

                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {isKhmer
                            ? 'ឈ្មោះ'
                            : 'Name'}

                          <span
                            className="
                              text-red-600
                              ml-1
                            "
                          >
                            *
                          </span>

                        </label>


                        <input
                          type="text"

                          name={
                            nameField
                          }

                          value={
                            formData[
                              nameField
                            ]
                          }

                          onChange={
                            handleChange
                          }

                          placeholder={
                            isKhmer
                              ? 'បញ្ចូលឈ្មោះសមាជិក'
                              : 'Enter member name'
                          }

                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>


                      {/* POSITION */}

                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {isKhmer
                            ? 'តួនាទី'
                            : 'Position'}

                          <span
                            className="
                              text-red-600
                              ml-1
                            "
                          >
                            *
                          </span>

                        </label>


                        <input
                          type="text"

                          name={
                            positionField
                          }

                          value={
                            formData[
                              positionField
                            ]
                          }

                          onChange={
                            handleChange
                          }

                          placeholder={
                            isKhmer
                              ? 'ឧ. នាយកសាលា'
                              : 'e.g. School Principal'
                          }

                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>


                      {/* BIOGRAPHY */}

                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {isKhmer
                            ? 'ជីវប្រវត្តិសង្ខេប'
                            : 'Biography'}
                        </label>


                        <textarea
                          name={
                            bioField
                          }

                          rows="5"

                          value={
                            formData[
                              bioField
                            ]
                          }

                          onChange={
                            handleChange
                          }

                          placeholder={
                            isKhmer
                              ? 'បញ្ចូលជីវប្រវត្តិសង្ខេប។'
                              : 'Enter biography.'
                          }

                          className="
                            w-full
                            px-4
                            py-3
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            resize-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>

                    </div>

                  </div>


                  {/* =================================================
                      CONTACT
                  ================================================== */}

                  <div
                    className="
                      border
                      border-blue-200
                      rounded-xl
                      overflow-hidden
                      mb-5
                    "
                  >

                    <div
                      className="
                        px-4
                        py-3
                        bg-blue-50
                        border-b
                        border-blue-200
                      "
                    >

                      <h3
                        className="
                          text-sm
                          font-bold
                          text-blue-900
                        "
                      >
                        {tr(
                          'leadership.contact',
                          'Contact',
                          'ទំនាក់ទំនង'
                        )}
                      </h3>

                    </div>


                    <div
                      className="
                        p-4
                        grid
                        grid-cols-1
                        md:grid-cols-2
                        gap-4
                      "
                    >

                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {isKhmer
                            ? 'អ៊ីមែល'
                            : 'Email'}
                        </label>


                        <input
                          type="email"

                          name="email"

                          value={
                            formData.email
                          }

                          onChange={
                            handleChange
                          }

                          placeholder="example@scacademy.edu.kh"

                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>


                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {tr(
                            'leadership.phone',
                            'Phone',
                            'លេខទូរស័ព្ទ'
                          )}
                        </label>


                        <input
                          type="text"

                          name="phone"

                          value={
                            formData.phone
                          }

                          onChange={
                            handleChange
                          }

                          placeholder="012 345 678"

                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>


                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          Facebook
                        </label>


                        <input
                          type="url"

                          name="facebook_url"

                          value={
                            formData.facebook_url
                          }

                          onChange={
                            handleChange
                          }

                          placeholder="https://facebook.com/..."

                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>


                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          LinkedIn
                        </label>


                        <input
                          type="url"

                          name="linkedin_url"

                          value={
                            formData.linkedin_url
                          }

                          onChange={
                            handleChange
                          }

                          placeholder="https://linkedin.com/in/..."

                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>

                    </div>

                  </div>


                  {/* =================================================
                      SETTINGS
                  ================================================== */}

                  <div
                    className="
                      border
                      border-blue-200
                      rounded-xl
                      p-4
                    "
                  >

                    <div
                      className="
                        grid
                        grid-cols-1
                        md:grid-cols-2
                        gap-5
                      "
                    >

                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {tr(
                            'leadership.order',
                            'Display Order',
                            'លំដាប់បង្ហាញ'
                          )}
                        </label>


                        <input
                          type="number"

                          name="order"

                          min="0"

                          value={
                            formData.order
                          }

                          onChange={
                            handleChange
                          }

                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            text-sm
                            text-blue-900
                            outline-none
                            focus:border-blue-900
                            focus:ring-2
                            focus:ring-blue-900/10
                            transition
                          "
                        />

                      </div>


                      <div
                        className="
                          flex
                          items-end
                        "
                      >

                        <div
                          className="
                            w-full
                            h-11
                            px-4
                            border
                            border-blue-200
                            rounded-lg
                            bg-blue-50
                            flex
                            items-center
                            justify-between
                          "
                        >

                          <div>

                            <p
                              className="
                                text-sm
                                font-semibold
                                text-blue-900
                              "
                            >
                              {formData.is_active
                                ? tr(
                                    'common.active',
                                    'Active',
                                    'សកម្ម'
                                  )
                                : tr(
                                    'common.inactive',
                                    'Inactive',
                                    'អសកម្ម'
                                  )}
                            </p>

                          </div>


                          <label
                            className="
                              relative
                              inline-flex
                              items-center
                              cursor-pointer
                            "
                          >

                            <input
                              type="checkbox"

                              name="is_active"

                              checked={
                                formData.is_active
                              }

                              onChange={
                                handleChange
                              }

                              className="
                                sr-only
                                peer
                              "
                            />


                            <div
                              className="
                                relative
                                w-11
                                h-6
                                bg-blue-200
                                rounded-full
                                peer
                                peer-checked:bg-blue-600

                                after:content-['']
                                after:absolute
                                after:top-[2px]
                                after:left-[2px]
                                after:w-5
                                after:h-5
                                after:bg-white
                                after:rounded-full
                                after:transition-all

                                peer-checked:after:translate-x-5
                              "
                            />

                          </label>

                        </div>

                      </div>

                    </div>

                  </div>

                </div>


                {/* =================================================
                    MODAL FOOTER
                ================================================== */}

                <div
                  className="
                    px-5
                    md:px-6
                    py-4
                    bg-blue-50
                    border-t
                    border-blue-200
                    flex
                    flex-col-reverse
                    sm:flex-row
                    items-stretch
                    sm:items-center
                    justify-end
                    gap-3
                    flex-shrink-0
                  "
                >

                  <button
                    type="button"

                    onClick={
                      handleCloseModal
                    }

                    disabled={
                      saving
                    }

                    className="
                      h-10
                      px-4
                      bg-white
                      border
                      border-blue-200
                      text-blue-400
                      rounded-lg
                      text-sm
                      font-semibold
                      hover:bg-blue-50
                      disabled:opacity-50
                      disabled:cursor-not-allowed
                      transition
                    "
                  >
                    {tr(
                      'common.cancel',
                      'Cancel',
                      'បោះបង់'
                    )}
                  </button>


                  <button
                    type="submit"

                    disabled={
                      saving
                    }

                    className="
                      min-w-[140px]
                      h-10
                      px-5
                      bg-red-600
                      text-white
                      rounded-lg
                      text-sm
                      font-semibold
                      inline-flex
                      items-center
                      justify-center
                      hover:bg-red-700
                      disabled:opacity-60
                      disabled:cursor-not-allowed
                      transition
                    "
                  >

                    {
                      saving ? (

                        <>

                          <span
                            className="
                              w-4
                              h-4
                              border-2
                              border-white/30
                              border-t-white
                              rounded-full
                              animate-spin
                              mr-2
                            "
                          />


                          {tr(
                            'common.saving',
                            'Saving...',
                            'កំពុងរក្សាទុក...'
                          )}

                        </>

                      ) : editingMember ? (

                        tr(
                          'leadership.updateMember',
                          'Update Member',
                          'កែប្រែសមាជិក'
                        )

                      ) : (

                        tr(
                          'leadership.addMember',
                          'Add Member',
                          'បន្ថែមសមាជិក'
                        )

                      )
                    }

                  </button>

                </div>

              </form>

            </div>

          </div>

        )
      }

    </div>

  );

};


export default AdminLeadership;
